document.addEventListener("DOMContentLoaded",()=>{const t=document.getElementById("actionsModal"),s=document.getElementById("actionsModalBg"),d=document.getElementById("notesModal"),n=document.querySelector(".notesModalBg"),o=document.querySelectorAll(".closeButton");document.addEventListener("keydown",function(e){e.key==="Escape"&&(t.classList.contains("hidden")&&d.classList.add("hidden"),d.classList.contains("hidden")&&t.classList.add("hidden"))}),o.forEach(e=>{e.addEventListener("click",a=>{a.preventDefault(),t.classList.add("hidden"),d.classList.add("hidden")})}),s.addEventListener("click",e=>{e.preventDefault(),t.classList.add("hidden")}),n!==null&&n.addEventListener("click",e=>{e.preventDefault(),d.classList.add("hidden")})});
